# ---- runtime: unsigned divmod ----
__udivmod:
    mv   t0, a0              # t0 = dividend
    mv   t1, a1              # t1 = divisor
    bne  t1, zero, __udm_nz
    li   a0, -1
    mv   a1, t0
    ret
__udm_nz:
    li   t2, 0               # quotient
    li   t3, 0               # remainder
    li   t4, 31              # bit index
__udm_loop:
    slli t3, t3, 1
    srl  t5, t0, t4
    andi t5, t5, 1
    or   t3, t3, t5          # r = (r<<1) | bit i of dividend
    bltu t3, t1, __udm_skip
